#include <iostream>

int main() {
    // Demonstrating precedence: * vs +, and right-to-left assignment
    int a = 2, b = 3, c = 4;
    int res1 = a + b * c; // b * c evaluated first -> 2 + 12 = 14
    std::cout << "res1: " << res1 << "\n";

    // Demonstrating right-to-left associativity of assignment
    int x, y, z;
    x = y = z = 10; // z = 10 -> y = 10 -> x = 10
    std::cout << "x: " << x << " y: " << y << " z: " << z << "\n";

    // Bitwise & vs equality == (== has higher precedence than &!)
    int flag = 6; // binary 0110
    // flag & 2 == 2 is parsed as flag & (2 == 2) -> 6 & 1 = 0
    int bad_check = flag & 2 == 2;
    int good_check = (flag & 2) == 2; // correct grouping -> (2) == 2 -> 1
    std::cout << "bad_check: " << bad_check << " good_check: " << good_check << "\n";

    return 0;
}

#include <iostream>

struct Widget {
    int val = 42;
    void display() const {
        std::cout << "Widget val: " << val << "\n";
    }
};

int global_x = 100;

int main() {
    int global_x = 5;
    // Unary scope resolution operator :: accesses global scope
    std::cout << "Local: " << global_x << ", Global: " << ::global_x << "\n";

    // C++ explicit cast static_cast
    double pi = 3.14159;
    int truncated = static_cast<int>(pi);
    std::cout << "Truncated pi: " << truncated << "\n";

    // Pointer to member operator .*
    Widget w;
    int Widget::* memberPtr = &Widget::val;
    std::cout << "Access via .*: " << w.*memberPtr << "\n";

    void (Widget::* funcPtr)() const = &Widget::display;
    (w.*funcPtr)(); // Parentheses required because () has higher precedence than .*

    return 0;
}
